:root {
  color-scheme: light dark;
  --accent: #0f766e;
  --border: #d6d3d1;
  --bg: #fafaf9;
  --text: #1c1917;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}

#app {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

#note-form {
  display: grid;
  gap: 0.5rem;
  padding: 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: white;
  margin-bottom: 1.5rem;
}

#note-form label {
  font-size: 0.85rem;
  font-weight: 600;
}

#note-form input,
#note-form textarea {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font: inherit;
}

#note-form textarea {
  min-height: 5rem;
  resize: vertical;
}

#note-form button {
  justify-self: start;
  padding: 0.5rem 1.25rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: white;
  font-weight: 600;
  cursor: pointer;
}

#note-form button:hover {
  filter: brightness(1.1);
}

.search-wrap {
  margin-bottom: 1rem;
}

#search {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font: inherit;
}

#results-line {
  margin: 0.4rem 0 0;
  font-size: 0.85rem;
  color: #57534e;
}

#feed {
  display: grid;
  gap: 0.75rem;
}

.note {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.85rem 1rem;
  background: white;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 0.75rem;
}

.note[aria-current="true"] {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.note-avatar {
  grid-row: 1 / 3;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}

.note-title {
  margin: 0;
  font-size: 1.05rem;
  cursor: pointer;
  display: inline-block;
  width: fit-content;
}

.note-title:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.note-body {
  margin: 0;
  line-height: 1.4;
  word-wrap: break-word;
}

.note-body a {
  color: var(--accent);
}

.note-time {
  grid-column: 2;
  font-size: 0.75rem;
  color: #78716c;
}

.empty-state {
  color: #78716c;
  font-style: italic;
}

