1	#!/usr/bin/env node
2	// Functional smoke check: build, serve, open the app in a headless browser, report console errors.
3	import { spawn, spawnSync } from 'node:child_process';
4	import path from 'node:path';
5	import { chromium } from '@playwright/test';
6	
7	const dir = import.meta.dirname;
8	const build = spawnSync('pnpm', ['build'], { cwd: dir, stdio: 'inherit' });
9	if (build.status !== 0) process.exit(build.status ?? 1);
10	
11	const port = 4300 + Math.floor(Math.random() * 500);
12	const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
13	await new Promise((r) => setTimeout(r, 500));
14	let failed = false;
15	try {
16	  const browser = await chromium.launch();
17	  const page = await browser.newPage();
18	  const errors = [];
19	  page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
20	  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
21	  await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: 'load' });
22	  await page.waitForTimeout(500);
